INSERT INTO "creative_process" ("id", "step_number", "title", "description", "sort_order", "is_active", "created_at", "updated_at") VALUES (29, '05', 'AUDIO & SFX', 'Layering immersive sound effects, Foley elements, dialogue noise reduction, and final audio mastering.', 5, true, '2026-09-23T07:05:12.193Z', '2026-09-23T07:05:12.193Z') ON CONFLICT DO NOTHING;
INSERT INTO "creative_process" ("id", "step_number", "title", "description", "sort_order", "is_active", "created_at", "updated_at") VALUES (30, '06', 'DELIVER & OPTIMIZE', 'Final rendering in multi-format aspect ratios (16:9, 9:16, 1:1, 4:5) optimized for web, broadcast, and social media.', 6, true, '2026-09-23T07:05:12.193Z', '2026-09-23T07:05:12.193Z') ON CONFLICT DO NOTHING;
